<?php
namespace App\Controllers;
use App\Core\{CSRF,Database,Encryption,RateLimiter,View};use App\Services\{ProductEvent,LegalDocumentService,PlatformSetting};
final class CommercialController
{
 public function landing():void{$host=mb_strtolower(preg_replace('/:\d+$/','',(string)($_SERVER['HTTP_HOST']??'')));if($host!==''){$q=Database::connection()->prepare("SELECT t.public_slug,t.public_short_code FROM tenant_domains d JOIN tenants t ON t.id=d.tenant_id WHERE d.domain=:host AND d.status='verified' AND t.status IN('trial','active') AND t.public_enabled=1 AND t.public_booking_enabled=1 AND t.deleted_at IS NULL AND COALESCE(t.is_demo,0)=0 LIMIT 1");$q->execute(['host'=>$host]);if($tenant=$q->fetch()){(new PublicBookingController())->show((string)($tenant['public_slug']?:$tenant['public_short_code']));return;}}$plans=$this->plans();$proof=$this->proof();$utm=[];foreach(['utm_source','utm_medium','utm_campaign','utm_content','utm_term'] as $key)if(isset($_GET[$key]))$utm[$key]=mb_substr(preg_replace('/[^\pL\pN._-]/u','',(string)$_GET[$key]),0,100);ProductEvent::record('LANDING_VIEW',null,null,$utm+['referrer'=>mb_substr((string)($_SERVER['HTTP_REFERER']??''),0,300)]);$growth=[];foreach(['hero_title','hero_subtitle','cta_label','meta_pixel_id','whatsapp','instagram','default_utm_campaign'] as $key)$growth[$key]=PlatformSetting::get('growth.'.$key,'');View::render('commercial/landing',['title'=>'Agenda, clientes e crescimento em um só lugar','plans'=>$plans,'proof'=>$proof,'growth'=>$growth,'publicLayout'=>true]);}
 public function plansPage():void{$plans=$this->plans();if(!$plans){header('Location: /interesse-comercial');exit;}ProductEvent::record('PLAN_VIEW');View::render('commercial/plans',['title'=>'Planos','plans'=>$plans,'publicLayout'=>true]);}
 public function signup():void{$plans=$this->plans();$offer=(string)($_GET['offer']??'');if(preg_match('/^[a-f0-9]{32}$/',$offer)){$q=Database::connection()->prepare("SELECT p.* FROM commercial_proposals cp JOIN plans p ON p.id=cp.plan_id WHERE cp.public_token=:t AND cp.status NOT IN('expired','cancelled','converted') AND (cp.expires_at IS NULL OR cp.expires_at>NOW()) AND p.active=1 LIMIT 1");$q->execute(['t'=>$offer]);if($private=$q->fetch())$plans=[$private];}$legal=LegalDocumentService::published();ProductEvent::record('SIGNUP_STARTED');View::render('commercial/signup',['title'=>'Começar teste grátis','plans'=>$plans,'legal'=>$legal,'publicLayout'=>true,'selected'=>(int)($_GET['plan']??0),'offer'=>$offer,'error'=>$_SESSION['flash_error']??null]);unset($_SESSION['flash_error']);}
 public function register():void
 {CSRF::enforce();$ip=$_SERVER['REMOTE_ADDR']??'unknown';if(!RateLimiter::hit('signup|'.$ip,5,3600)){http_response_code(429);exit('Muitas tentativas.');}$owner=trim((string)($_POST['owner_name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$phone=preg_replace('/\D/','',(string)($_POST['phone']??''));$company=trim((string)($_POST['company_name']??''));$category=trim((string)($_POST['category']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirmation']??'');$planId=filter_var($_POST['plan_id']??null,FILTER_VALIDATE_INT);$offer=(string)($_POST['offer']??'');$validPassword=strlen($password)>=12&&preg_match('/[A-Z]/',$password)&&preg_match('/[a-z]/',$password)&&preg_match('/\d/',$password)&&hash_equals($password,$confirm);if(strlen($owner)<2||strlen($company)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($phone)<10||!$validPassword||!$planId||!isset($_POST['terms'])){$_SESSION['flash_error']='Revise os dados, a senha e o aceite dos termos.';header('Location: /cadastro?plan='.(int)$planId);exit;}$pdo=Database::connection();$plan=$pdo->prepare('SELECT * FROM plans WHERE id=:id AND active=1 AND trial_without_card=1');$plan->execute(['id'=>$planId]);$plan=$plan->fetch();if($plan&&empty($plan["is_custom"])&&empty($plan["public_visible"]))$plan=false;if($plan&&!empty($plan["is_custom"])){$offerCheck=$pdo->prepare("SELECT 1 FROM commercial_proposals WHERE plan_id=:plan AND public_token=:token AND status NOT IN('expired','cancelled','converted') AND (expires_at IS NULL OR expires_at>NOW()) AND EXISTS(SELECT 1 FROM proposal_acceptances pa WHERE pa.proposal_id=commercial_proposals.id)");$offerCheck->execute(["plan"=>$planId,"token"=>$offer]);if(!preg_match("/^[a-f0-9]{32}$/",$offer)||!$offerCheck->fetchColumn())$plan=false;}if(!$plan){http_response_code(422);exit('Plano indisponível para teste sem cartão.');}$slug=$this->uniqueSlug($pdo,$company);$token=bin2hex(random_bytes(32));$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO tenants(name,slug,public_slug,email,phone,category,description,status,public_enabled,public_booking_enabled,onboarding_step,created_at,updated_at)VALUES(:name,:slug,:public_slug,:email,:phone,:category,NULL,'trial',1,1,1,NOW(),NOW())")->execute(['name'=>$company,'slug'=>$slug,'public_slug'=>$slug,'email'=>$email,'phone'=>$phone,'category'=>$category]);$tenant=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO users(tenant_id,name,email,password_hash,status,created_at,updated_at)VALUES(:tenant,:name,:email,:password,'active',NOW(),NOW())")->execute(['tenant'=>$tenant,'name'=>$owner,'email'=>$email,'password'=>password_hash($password,PASSWORD_DEFAULT)]);$user=(int)$pdo->lastInsertId();$role=(int)$pdo->query("SELECT id FROM roles WHERE slug='owner'")->fetchColumn();$pdo->prepare('INSERT INTO user_roles(user_id,role_id)VALUES(:user,:role)')->execute(['user'=>$user,'role'=>$role]);$days=(int)$plan['trial_days'];$pdo->prepare("INSERT INTO subscriptions(tenant_id,plan_id,billing_cycle,contracted_price,status,started_at,trial_ends_at,next_billing_at,created_at,updated_at)VALUES(:tenant,:plan,'monthly',:price,'trial',NOW(),DATE_ADD(NOW(),INTERVAL :days DAY),DATE_ADD(NOW(),INTERVAL :days2 DAY),NOW(),NOW())")->execute(['tenant'=>$tenant,'plan'=>$planId,'price'=>$plan['monthly_price'],'days'=>$days,'days2'=>$days]);$pdo->prepare('INSERT INTO tenant_onboarding(tenant_id,updated_at)VALUES(:tenant,NOW())')->execute(['tenant'=>$tenant]);if(!empty($plan["is_custom"])) {$pdo->prepare("UPDATE commercial_proposals SET tenant_id=:tenant,status='converted',updated_at=NOW() WHERE plan_id=:plan AND public_token=:offer AND status NOT IN('expired','cancelled','converted')")->execute(["tenant"=>$tenant,"plan"=>$planId,"offer"=>$offer]);$pdo->prepare("INSERT IGNORE INTO commercial_commissions(commercial_user_id,tenant_id,base_amount,commission_percent,commission_amount,status,created_at,updated_at) SELECT cp.commercial_user_id,:tenant,:price,pr.commission_percent,ROUND(:price2*pr.commission_percent/100,2),'projected',NOW(),NOW() FROM commercial_proposals cp JOIN commercial_profiles pr ON pr.user_id=cp.commercial_user_id AND pr.active=1 WHERE cp.plan_id=:plan AND cp.public_token=:offer")->execute(["tenant"=>$tenant,"price"=>$plan["monthly_price"],"price2"=>$plan["monthly_price"],"plan"=>$planId,"offer"=>$offer]);}$legal=LegalDocumentService::published();foreach($legal as $doc){if(!$doc)throw new \RuntimeException('Documentos legais vigentes não publicados.');$pdo->prepare("INSERT IGNORE INTO legal_acceptances(document_id,tenant_id,user_id,ip_address,user_agent,accepted_at)VALUES(:document,:tenant,:user,:ip,:ua,NOW())")->execute(['document'=>$doc['id'],'tenant'=>$tenant,'user'=>$user,'ip'=>$ip,'ua'=>substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500)]);}$pdo->prepare("INSERT INTO terms_acceptances(tenant_id,user_id,terms_version,ip_address,accepted_at)VALUES(:tenant,:user,:version,:ip,NOW())")->execute(['tenant'=>$tenant,'user'=>$user,'version'=>$legal['terms']['version']??'1.0','ip'=>$ip]);$pdo->prepare('INSERT INTO email_verification_tokens(user_id,token_hash,expires_at,created_at)VALUES(:user,:hash,DATE_ADD(NOW(),INTERVAL 24 HOUR),NOW())')->execute(['user'=>$user,'hash'=>hash('sha256',$token)]);$app=require __DIR__.'/../../config/app.php';$payload=Encryption::encrypt(['to'=>$email,'template'=>'email_verification','url'=>rtrim($app['url'],'/').'/verify-email?token='.$token]);$pdo->prepare("INSERT INTO jobs(tenant_id,type,payload_encrypted,status,attempts,available_at,created_at,updated_at)VALUES(:tenant,'mail.send',:payload,'queued',0,NOW(),NOW(),NOW())")->execute(['tenant'=>$tenant,'payload'=>$payload]);$pdo->commit();ProductEvent::record('SIGNUP_COMPLETED',$tenant,$user,['plan_id'=>$planId]);ProductEvent::record('TRIAL_STARTED',$tenant,$user,['days'=>$days]);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}if(!\App\Core\Auth::attempt($email,$password)){header('Location: /login');exit;}header('Location: /onboarding');exit;}
 public function segmentLanding(string $segment):void{$segment=\App\Services\GrowthService::segment($segment);if(!$segment){http_response_code(404);View::render('dashboard/404',['title'=>'Segmento não encontrado','publicLayout'=>true]);return;}$copy=['barber'=>['Agenda e operação para barbearias que querem crescer.','Organize profissionais, fila, comandas, produtos, comissão e retorno dos clientes.'],'arena'=>['Sua Arena disponível para reservas 24 horas por dia.','Gerencie quadras, rachas, mensalistas, aulas, torneios, comandas e pagamentos.'],'auto'=>['Do agendamento à entrega do veículo, tudo sob controle.','Organize boxes, checklist, fotos, orçamento, estoque, comandas e relacionamento por veículo.'],'estetica'=>['Uma experiência de agendamento à altura da sua marca.','Agenda, clientes, profissionais, pacotes, fidelidade e financeiro para estética.'],'saude'=>['Agenda organizada e relacionamento contínuo com pacientes.','Disponibilidade, lembretes, histórico e operação para consultórios e serviços de saúde.'],'salao'=>['Menos horários vazios. Mais clientes que retornam.','Agenda por profissional, serviços, produtos, comissões, pacotes e fidelidade.']][$segment];$growth=['hero_title'=>$copy[0],'hero_subtitle'=>$copy[1],'cta_label'=>'Começar teste grátis','meta_pixel_id'=>PlatformSetting::get('growth.meta_pixel_id',''),'whatsapp'=>PlatformSetting::get('growth.whatsapp',''),'instagram'=>PlatformSetting::get('growth.instagram',''),'default_utm_campaign'=>PlatformSetting::get('growth.default_utm_campaign','')];$_GET['segment']=$segment;$plans=$this->plans();$proof=$this->proof();\App\Services\GrowthService::record('PageView',['segment'=>$segment]);ProductEvent::record('LANDING_SEGMENT_VIEW',null,null,['segment'=>$segment]);View::render('commercial/landing',['title'=>$copy[0],'plans'=>$plans,'proof'=>$proof,'growth'=>$growth,'segment'=>$segment,'publicLayout'=>true]);}
 private function plans():array{$pdo=Database::connection();$plans=$pdo->query('SELECT * FROM plans WHERE active=1 AND public_visible=1 AND is_custom=0 ORDER BY sort_order,monthly_price')->fetchAll();foreach($plans as &$p){$q=$pdo->prepare('SELECT m.name,m.slug,m.description FROM plan_modules pm JOIN modules m ON m.id=pm.module_id WHERE pm.plan_id=:p AND pm.enabled=1 AND m.active=1 ORDER BY m.sort_order,m.name');$q->execute(['p'=>$p['id']]);$p['modules']=$q->fetchAll();}return $plans;}
 private function proof():array{$pdo=Database::connection();$out=['businesses'=>0,'appointments'=>0,'rating'=>0.0,'reviews'=>0];try{$out['businesses']=(int)$pdo->query("SELECT COUNT(*) FROM tenants WHERE status IN('trial','active') AND deleted_at IS NULL AND COALESCE(is_demo,0)=0")->fetchColumn();$out['appointments']=(int)$pdo->query("SELECT COUNT(*) FROM appointments a JOIN tenants t ON t.id=a.tenant_id WHERE a.status IN('confirmed','completed') AND COALESCE(t.is_demo,0)=0")->fetchColumn();$r=$pdo->query("SELECT COALESCE(AVG(pr.rating),0) rating,COUNT(*) reviews FROM public_reviews pr JOIN tenants t ON t.id=pr.tenant_id WHERE pr.active=1 AND COALESCE(t.is_demo,0)=0")->fetch();$out['rating']=(float)($r['rating']??0);$out['reviews']=(int)($r['reviews']??0);}catch(\Throwable $e){error_log('[ApPlanner Landing Proof] '.$e->getMessage());}return$out;}
 private function uniqueSlug(\PDO $pdo,string $name):string{$ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:$name;$base=trim(preg_replace('/[^a-z0-9]+/','-',strtolower($ascii)),'-')?:'empresa';$slug=$base;$i=2;$s=$pdo->prepare('SELECT 1 FROM tenants WHERE slug=:slug');while(true){$s->execute(['slug'=>$slug]);if(!$s->fetchColumn())return $slug;$slug=$base.'-'.$i++;}}
}
